// One-time schema addition: creates the programRankings table (see
// lib/db/schema.ts). Run once; drizzle-kit push hangs on introspection in
// this environment, so this mirrors migrate-tier-rename.mjs's raw-SQL
// approach instead of fighting that.
// Usage: node --env-file=.env.local scripts/migrate-add-program-rankings.mjs

import { neon } from '@neondatabase/serverless'

const sql = neon(process.env.DATABASE_URL)

await sql`
  CREATE TABLE IF NOT EXISTS "programRankings" (
    "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "universityId" integer NOT NULL,
    "field" text NOT NULL,
    "rankValue" integer,
    "rankSource" text NOT NULL,
    "rankSourceUrl" text NOT NULL,
    "acceptanceRate" integer,
    "programSelectivity" integer NOT NULL,
    "notes" text,
    "createdAt" timestamp NOT NULL DEFAULT now()
  )
`
console.log('programRankings table created (or already existed).')

const check = await sql`
  SELECT column_name, data_type, is_nullable
  FROM information_schema.columns
  WHERE table_name = 'programRankings'
  ORDER BY ordinal_position
`
console.table(check)
